import type { Elements, On, RenderElement } from 'claude-code'

import { highlight } from '../code/highlight'
import { cachedEnv } from '../env'
import { flagsVersion, getFlags } from '../flags'
import { lang, pick, tr, type Text } from '../i18n'
import { memo } from '../memo'
import { CODE, SCREEN, type ScreenTone } from '../palette'
import type { Explanation, TestScore } from '../../types'
import { CARD_TONE, cardText, commitCards, type CommitCard } from './commit'
import { isAnswerExit, rememberAnswer, wasAnswer } from './explainError'
import { commitFor, explanationFor } from './notes'
import { formatScore, parseTestSummary } from './score'
import { asRecord, bashText, EDIT_TOOLS, editCounts, editedPath, shortPath, str } from './toolInfo'
import { timed } from '../perf'

type T = Pick<Elements['terminal'], 'Box' | 'Text'>

export type ToolKind = 'read' | 'edit' | 'run' | 'agent' | 'web' | 'plan' | 'mcp'

export type ToolSummary = { kind: ToolKind; icon: string; verb: string; target: string; added?: number; removed?: number; isNew?: boolean }

const READ_VERBS: Record<string, Text> = {
  Read: { en: 'Read', pt: 'Leu' },
  NotebookRead: { en: 'Read', pt: 'Leu' },
  Grep: { en: 'Searched', pt: 'Buscou' },
  Glob: { en: 'Looked for', pt: 'Procurou' },
  LS: { en: 'Listed', pt: 'Listou' },
}

const TASK_STATUS: Record<string, Text> = {
  pending: { en: 'pending', pt: 'pendente' },
  in_progress: { en: 'in progress', pt: 'em andamento' },
  completed: { en: 'done', pt: 'concluída' },
  deleted: { en: 'removed', pt: 'removida' },
}

/** A tool call as one row of its kind; null for a tool this mod leaves to the engine. */
export function summarizeTool(tool: string, input: unknown, cwd: string | null, output?: unknown): ToolSummary | null {
  const inp = asRecord(input)
  const path = (key: string) => shortPath(str(inp[key]) ?? '', cwd)
  if (tool in READ_VERBS) {
    const target = tool === 'Grep' || tool === 'Glob' ? str(inp.pattern) ?? '' : path(tool === 'NotebookRead' ? 'notebook_path' : tool === 'LS' ? 'path' : 'file_path')
    return { kind: 'read', icon: '◇', verb: pick(READ_VERBS[tool]!), target }
  }
  if (EDIT_TOOLS.has(tool)) {
    const { added, removed, isNew } = editCounts(tool, input, output)
    return { kind: 'edit', icon: '✎', verb: tool === 'Write' ? tr('Wrote', 'Escreveu') : tr('Edited', 'Editou'), target: shortPath(editedPath(input) ?? '', cwd), added, removed, isNew }
  }
  if (tool === 'Bash') return { kind: 'run', icon: '▶', verb: '', target: str(inp.command) ?? '' }
  if (tool === 'BashOutput') return { kind: 'run', icon: '▶', verb: tr('Output of', 'Saída de'), target: str(inp.bash_id) ?? '' }
  if (tool === 'KillShell') return { kind: 'run', icon: '▶', verb: tr('Stopped', 'Encerrou'), target: str(inp.shell_id) ?? '' }
  if (tool === 'Agent' || tool === 'Task') {
    const type = str(inp.subagent_type)
    return { kind: 'agent', icon: '◆', verb: type ? tr(`Agent ${type}:`, `Agente ${type}:`) : tr('Agent:', 'Agente:'), target: str(inp.description) ?? '' }
  }
  if (tool === 'WebSearch') return { kind: 'web', icon: '◎', verb: tr('Searched:', 'Buscou:'), target: str(inp.query) ?? '' }
  if (tool === 'WebFetch') return { kind: 'web', icon: '◎', verb: tr('Opened:', 'Abriu:'), target: str(inp.url) ?? '' }
  if (tool === 'TodoWrite') {
    const todos = Array.isArray(inp.todos) ? inp.todos.map(asRecord) : []
    return { kind: 'plan', icon: '☰', verb: tr('Plan:', 'Plano:'), target: `${todos.filter(t => t.status === 'completed').length}/${todos.length}` }
  }
  if (tool === 'TaskCreate') return { kind: 'plan', icon: '☰', verb: tr('Plan:', 'Plano:'), target: `+ ${str(inp.subject) ?? ''}` }
  if (tool === 'TaskUpdate') {
    const status = str(inp.status)
    return { kind: 'plan', icon: '☰', verb: tr('Plan:', 'Plano:'), target: `#${str(inp.taskId) ?? '?'} ${status !== null ? (TASK_STATUS[status] === undefined ? status : pick(TASK_STATUS[status])) : tr('updated', 'atualizada')}` }
  }
  if (tool === 'TaskList') return { kind: 'plan', icon: '☰', verb: tr('Plan:', 'Plano:'), target: tr('list', 'lista') }
  if (tool === 'TaskGet') return { kind: 'plan', icon: '☰', verb: tr('Plan:', 'Plano:'), target: `#${str(inp.taskId) ?? '?'}` }
  const mcp = /^mcp__(.+?)__(.+)$/.exec(tool)
  if (mcp !== null) return { kind: 'mcp', icon: '⬡', verb: '', target: `${mcp[1]} · ${mcp[2]}` }
  return null
}

// A folded group's words per tool: verb, one, many.
type GroupWords = readonly [string, string, string]
const GROUP_WORDS: Record<string, { en: GroupWords; pt: GroupWords }> = {
  Read: { en: ['read', 'file', 'files'], pt: ['leu', 'arquivo', 'arquivos'] },
  NotebookRead: { en: ['read', 'file', 'files'], pt: ['leu', 'arquivo', 'arquivos'] },
  Grep: { en: ['searched', 'time', 'times'], pt: ['buscou', 'vez', 'vezes'] },
  Glob: { en: ['looked for', 'pattern', 'patterns'], pt: ['procurou', 'padrão', 'padrões'] },
  LS: { en: ['listed', 'folder', 'folders'], pt: ['listou', 'pasta', 'pastas'] },
  Bash: { en: ['ran', 'command', 'commands'], pt: ['rodou', 'comando', 'comandos'] },
}
const OTHER_WORDS: { en: GroupWords; pt: GroupWords } = { en: ['used', 'other tool', 'other tools'], pt: ['usou', 'outra ferramenta', 'outras ferramentas'] }

/** 'Read 6 files · searched 3 times' ('Leu 6 arquivos · buscou 3 vezes'): what a folded group did, in its order. */
export function summarizeGroup(calls: readonly { tool: string; input: unknown }[]): string {
  const counts = new Map<GroupWords, number>()
  for (const call of calls) {
    const words = (GROUP_WORDS[call.tool] ?? OTHER_WORDS)[lang()]
    // Read and NotebookRead share one count.
    const key = [...counts.keys()].find(k => k[0] === words[0] && k[1] === words[1]) ?? words
    counts.set(key, (counts.get(key) ?? 0) + 1)
  }
  const text = [...counts].map(([[verb, one, many], n]) => `${verb} ${n} ${n === 1 ? one : many}`).join(' · ')
  return text.charAt(0).toUpperCase() + text.slice(1)
}

const DRAWN_TOOLS = [
  'Read', 'NotebookRead', 'Grep', 'Glob', 'LS', 'Edit', 'MultiEdit', 'Write', 'NotebookEdit', 'Bash', 'BashOutput', 'KillShell',
  'Agent', 'Task', 'WebSearch', 'WebFetch', 'TodoWrite', 'TaskCreate', 'TaskUpdate', 'TaskList', 'TaskGet', /^mcp__.+__.+$/,
]

const KIND_TONE: Record<ToolKind, ScreenTone> = { read: 'dim', edit: 'edit', run: 'run', agent: 'agent', web: 'web', plan: 'plan', mcp: 'mcp' }

type RowState = { isRunning: boolean; isErrored: boolean; isInterrupted: boolean; isAnswer?: boolean }

/**
 * Still running: no result yet. The engine keeps isRunning true on a call that resolved with files changed (seen with a
 * pytest that wrote caches), while `output` is the stored result "once the call has resolved", by its contract.
 */
export const isStillRunning = (call: { isRunning: boolean; output?: unknown }): boolean => call.isRunning && call.output === undefined

type CallState = { tool_use_id?: string; tool: string; input: unknown; isErrored: boolean; output?: unknown }

/**
 * An errored call whose exit is an answer (`grep` with no match, `test -f` false): it ran fine and said no. Told by
 * what tool.call saw; a call from before this load by the text it left, and one with no text (a folded group's) stays
 * the engine's error.
 */
export function isAnswered(call: CallState): boolean {
  if (!call.isErrored || call.tool !== 'Bash') return false
  if (call.tool_use_id !== undefined && wasAnswer(call.tool_use_id)) return true
  const isAnswer = typeof call.output === 'string' && isAnswerExit(str(asRecord(call.input).command) ?? '', call.output)
  // Told by its text: kept, so its result row (which carries no command) is told the same.
  if (isAnswer && call.tool_use_id !== undefined) rememberAnswer(call.tool_use_id)
  return isAnswer
}

const hasFailed = (call: CallState): boolean => call.isErrored && !isAnswered(call)

function shellLine(t: T, line: string): RenderElement[] {
  const { Text } = t
  return (highlight(line, 'sh')[0] ?? []).map(tok => (tok.kind ? <Text {...CODE[tok.kind]}>{tok.text}</Text> : tok.text) as RenderElement)
}

/** A git command as its cards, one line each, in place of the command. */
function cardRows(t: T, cards: readonly CommitCard[]): RenderElement {
  const { Box, Text } = t
  return (
    <Box key="realce-tool" flexDirection="column">
      {cards.map(card => (
        <Text color={SCREEN[CARD_TONE[card.kind]]} wrap="truncate-end">
          {cardText(card)}
        </Text>
      ))}
    </Box>
  )
}

/** The sentence under a failed command: while the model writes it, then it or why there is none. */
function whyLine(t: T, why: Explanation): RenderElement {
  const { Box, Text } = t
  // The box holds the indent, so a long sentence wraps under itself and not at the left edge.
  return (
    <Box key="realce-why" paddingLeft={2}>
      {why.status === 'pending' ? (
        <Text color={SCREEN.dim}>{tr('↳ Explaining…', '↳ Explicando…')}</Text>
      ) : why.status === 'failed' ? (
        <Text color={SCREEN.dim} wrap="truncate-end">{tr(`↳ No explanation: ${why.reason}`, `↳ Sem explicação: ${why.reason}`)}</Text>
      ) : why.status === 'cut' ? (
        <Text color={SCREEN.dim} wrap="truncate-end">{tr('↳ No explanation: cut short when the mod reloaded', '↳ Sem explicação: interrompida ao recarregar o mod')}</Text>
      ) : (
        <Text color={SCREEN.warn}>{tr(`↳ Why: ${why.text}`, `↳ Por quê: ${why.text}`)}</Text>
      )}
    </Box>
  )
}

function toolRow(t: T, s: ToolSummary, state: RowState, score: TestScore | null = null, why: Explanation | null = null): RenderElement {
  const { Box, Text } = t
  const icon = state.isRunning ? '◌' : state.isErrored ? '✖' : s.icon
  const head = s.verb === '' ? `${icon} ` : `${icon} ${s.verb} `
  const tail = state.isInterrupted ? <Text color={SCREEN.dim}>{tr(' · interrupted', ' · interrompida')}</Text> : state.isAnswer ? <Text color={SCREEN.dim}>{tr(' · no match', ' · sem resultado')}</Text> : null
  if (s.kind === 'run') {
    const lines = s.target.split('\n')
    const more = lines.length > 2 ? ' …' : ''
    return (
      <Box key="realce-tool" flexDirection="column">
        {lines.slice(0, 2).map((line, i) =>
          state.isErrored ? (
            <Text color={SCREEN.bad} wrap="truncate-end">{`${i === 0 ? head : '  '}${line}${i === 1 ? more : ''}`}</Text>
          ) : (
            <Text wrap="truncate-end">
              <Text color={SCREEN.run}>{i === 0 ? head : '  '}</Text>
              {shellLine(t, line)}
              {i === 1 && more}
              {i === Math.min(lines.length, 2) - 1 && tail}
            </Text>
          ),
        )}
        {why !== null && whyLine(t, why)}
        {score !== null && (
          <Box key="realce-score">
            <Text color={score.failed === 0 ? SCREEN.ok : SCREEN.bad} wrap="truncate-end">{`  ${formatScore(score)}`}</Text>
          </Box>
        )}
      </Box>
    )
  }
  if (state.isErrored) {
    return (
      <Box key="realce-tool">
        <Text color={SCREEN.bad} wrap="truncate-end">{`${head}${s.target}`}</Text>
      </Box>
    )
  }
  if (s.kind === 'edit') {
    const hasCounts = (s.added ?? 0) > 0 || (s.removed ?? 0) > 0 || s.isNew === true
    return (
      <Box key="realce-tool">
        <Text wrap="truncate-end">
          <Text color={SCREEN.edit}>{head}</Text>
          {s.target}
          {hasCounts && '  '}
          {hasCounts && <Text color={SCREEN.ok}>{`+${s.added ?? 0}`}</Text>}
          {hasCounts && (s.isNew ? <Text color={SCREEN.dim}>{tr(' (new)', ' (novo)')}</Text> : ' ')}
          {hasCounts && !s.isNew && <Text color={SCREEN.bad}>{`−${s.removed ?? 0}`}</Text>}
          {tail}
        </Text>
      </Box>
    )
  }
  return (
    <Box key="realce-tool">
      <Text color={SCREEN[KIND_TONE[s.kind]]} wrap="truncate-end">
        {`${head}${s.target}`}
        {tail}
      </Text>
    </Box>
  )
}

const isDrawnTool = (tool: string) => DRAWN_TOOLS.some(t => (typeof t === 'string' ? t === tool : t.test(tool)))

/** What focus mode leaves of a finished, unfailed row: nothing. */
function hiddenRow(t: Pick<Elements['terminal'], 'Box'>): RenderElement {
  const { Box } = t
  return <Box key="realce-hidden" />
}

export function registerTools(on: On): void {
  on('ui.render', { component: 'ToolUse' }, async ($, e, next) => timed('ToolUse', async () => {
    const flags = await getFlags($)
    if (e.surface !== 'terminal') return next(e)
    const { isInterrupted, output } = e.props
    const isRunning = isStillRunning(e.props)
    const isAnswer = isAnswered(e.props)
    const isErrored = hasFailed(e.props)
    // Focus mode hides what finished well, whatever the tool; running and failed calls stay in sight.
    if (flags.foco && !isRunning && !isErrored && !isInterrupted) return hiddenRow($.ui.resolve(e))
    // Only the tools summarizeTool draws: any other call stays the engine's.
    if (!flags.ferramentas || !isDrawnTool(e.props.tool)) return next(e)
    const cwd = cachedEnv()?.cwd ?? null
    // Only a failed command reads the explanations, so only those rows redraw when one arrives.
    const why: Explanation | null = flags.erros && isErrored && e.props.tool === 'Bash' ? explanationFor(e.props.tool_use_id) : null
    // A row changes only with its call's state: everything else is the same call drawn again.
    const key = `${e.requestId}|${isRunning}|${isErrored}|${isAnswer}|${isInterrupted}|${output === undefined}|${flagsVersion()}|${cwd}|${why === null ? '' : JSON.stringify(why)}`
    const row = memo('ToolUse', key, () => {
      // An errored call's output is the error text the model read, not the tool's result.
      const summary = summarizeTool(e.props.tool, e.props.input, cwd, e.props.isErrored ? undefined : output)
      const cards = flags.commits && e.props.tool === 'Bash' && !e.props.isErrored && output !== undefined ? commitCards(output) : []
      if (cards.length > 0) return cardRows($.ui.resolve(e), cards)
      // The test score rides the command's own row: a result hook cost a trip to the engine for every result drawn.
      const score = flags.placar && e.props.tool === 'Bash' && output !== undefined ? parseTestSummary(bashText(output)) : null
      return summary === null ? null : toolRow($.ui.resolve(e), summary, { isRunning, isErrored, isInterrupted, isAnswer }, score, why)
    })
    return row ?? next(e)
  }))

  on('ui.render', { component: 'ToolGroup' }, async ($, e, next) => timed('ToolGroup', async () => {
    const flags = await getFlags($)
    if (e.surface !== 'terminal') return next(e)
    const calls = e.props.calls
    if (flags.foco && !calls.some(c => isStillRunning(c) || hasFailed(c))) return hiddenRow($.ui.resolve(e))
    if (!flags.ferramentas || e.props.isExpanded) return next(e)
    const cards = flags.commits ? calls.flatMap(c => (c.tool_use_id === undefined ? [] : [commitFor(c.tool_use_id)].filter((x): x is string => x !== null))) : []
    // The folded group is what the screen shows: a failed command's sentence rides under it, the first one's.
    const failed = flags.erros ? calls.filter(c => hasFailed(c) && c.tool === 'Bash' && c.tool_use_id !== undefined) : []
    const why = failed.map(c => explanationFor(c.tool_use_id!)).find(w => w !== null) ?? null
    const key = `${e.requestId}|${flagsVersion()}|${calls.map(c => `${c.tool}${+isStillRunning(c)}${+hasFailed(c)}`).join(',')}|${cards.join(',')}|${why === null ? '' : JSON.stringify(why)}`
    return memo('ToolGroup', key, () => {
      const t = $.ui.resolve(e)
      const { Box, Text } = t
      const errored = calls.filter(hasFailed).length
      const icon = calls.some(isStillRunning) ? '◌' : '◇'
      return (
        <Box key="realce-group" flexDirection="column">
          <Text color={SCREEN.dim} wrap="truncate-end">
            {`${icon} ${summarizeGroup(calls)}`}
            {cards.length > 0 && <Text color={SCREEN.ok}>{` · ${cards.join(' · ')}`}</Text>}
            {errored > 0 && <Text color={SCREEN.bad}>{tr(` · ${errored} failed`, ` · ${errored} com erro`)}</Text>}
          </Text>
          {why !== null && whyLine(t, why)}
        </Box>
      )
    })
  }))

  // The result under a row focus mode hid goes with it; the edit tools' results are the diff's own hook.
  on('ui.render', { component: 'ToolResult' }, async ($, e, next) => {
    const flags = await getFlags($)
    // An answered call (a grep with no match) finished well: its result goes with its row.
    if (!flags.foco || e.surface !== 'terminal' || (e.props.isErrored && !wasAnswer(e.props.tool_use_id))) return next(e)
    return hiddenRow($.ui.resolve(e))
  })
}

files.hooks/screen/turns.tsx:
import { atom, read } from 'claude-code'
import type { Elements, On, RenderElement } from 'claude-code'

import type { Seal, TurnStats } from '../../types'
import { flagsVersion, getFlags } from '../flags'
import { memo } from '../memo'
import { formatClock, formatDuration, plural } from '../format'
import { tr } from '../i18n'
import { SCREEN } from '../palette'
import { timed } from '../perf'
import { cachedEnv } from '../env'

const TURNS = atom({ plugin: 'realce', key: 'turns' } as const, {})

type T = Pick<Elements['terminal'], 'Box' | 'Text'>

type Span = { text: string; color: string }

// The transcript leaves a cell on each side of a row; a rule that fills the viewport would wrap.
export const ruleWidth = (columns: number | undefined) => Math.max(10, (columns ?? 80) - 2)

export function testsLabel(stats: TurnStats): Span | null {
  const tests = stats.tests
  if (tests === null) return null
  if (tests.failed === 0) return { text: tr('✔ tests', '✔ testes'), color: SCREEN.ok }
  const noun =
    tests.unit === 'pacotes'
      ? [tr('package failed', 'pacote falhou'), tr('packages failed', 'pacotes falharam')]
      : [tr('test failed', 'teste falhou'), tr('tests failed', 'testes falharam')]
  return { text: `✖ ${plural(tests.failed, noun[0]!, noun[1]!)}`, color: SCREEN.bad }
}

export function sealLabel(seal: Seal | null | undefined): Span | null {
  if (seal === 'proved') return { text: tr('✔ proved', '✔ provado'), color: SCREEN.ok }
  if (seal === 'failing') return { text: tr('✖ claimed with tests failing', '✖ afirmou com testes falhando'), color: SCREEN.bad }
  if (seal === 'unproved') return { text: tr('⚠ no proof', '⚠ sem prova'), color: SCREEN.warn }
  return null
}

// `drop`: which goes first when the rule is too narrow (lowest first); a label without one always stays.
// `short`: what a kept label says when even the kept ones do not fit.
type Label = Span & { drop?: number; short?: string }

/** The labels as a rule filling `width`: '── a · b ───'; null when even the kept ones do not fit. */
function fillRule(labels: readonly Label[], width: number): Span[] | null {
  const length = (ls: readonly Label[]) => 4 + ls.reduce((n, l) => n + [...l.text].length, 0) + 3 * (ls.length - 1) + 2
  let shown = [...labels]
  // What does not fit drops by rank: the counts, then the clock, then the tests; the duration and the seal stay.
  while (length(shown) > width) {
    const droppable = shown.filter(l => l.drop !== undefined)
    if (droppable.length === 0) {
      // The verdict outlives its wording: a long seal takes its short form before the rule gives up.
      const long = shown.find(l => l.short !== undefined && l.text !== l.short)
      if (long === undefined) return null
      shown = shown.map(l => (l === long ? { ...l, text: l.short! } : l))
      continue
    }
    const first = droppable.reduce((a, b) => (b.drop! < a.drop! ? b : a))
    shown = shown.filter(l => l !== first)
  }
  const spans: Span[] = [{ text: '── ', color: SCREEN.rule }]
  shown.forEach((label, i) => {
    if (i > 0) spans.push({ text: ' · ', color: SCREEN.dim })
    spans.push({ text: label.text, color: label.color })
  })
  const used = spans.reduce((n, s) => n + [...s.text].length, 0)
  spans.push({ text: ` ${'─'.repeat(Math.max(0, width - used - 1))}`, color: SCREEN.rule })
  return spans
}

/** The turn's closing rule as colored runs: what does not fit the width drops, the duration and the seal stay. */
function ruleSpans(stats: TurnStats | null, durationMs: number, width: number, tzOffsetMinutes: number | null): Span[] {
  const labels: Label[] = []
  if (stats !== null && tzOffsetMinutes !== null) labels.push({ text: formatClock(stats.endedAt, tzOffsetMinutes), color: SCREEN.dim, drop: 3 })
  labels.push({ text: formatDuration(durationMs), color: SCREEN.dim })
  if (stats !== null) {
    const seal = sealLabel(stats.seal)
    if (seal !== null) labels.push({ ...seal, ...(stats.seal === 'failing' ? { short: tr('✖ failing', '✖ falhando') } : {}) })
    // A count of nothing says nothing: a turn that only answered draws its time alone.
    if (stats.tools > 0) labels.push({ text: plural(stats.tools, tr('tool', 'ferramenta'), tr('tools', 'ferramentas')), color: SCREEN.dim, drop: 2 })
    if (stats.files > 0) labels.push({ text: plural(stats.files, tr('file', 'arquivo'), tr('files', 'arquivos')), color: SCREEN.dim, drop: 1 })
    const tests = testsLabel(stats)
    if (tests !== null) labels.push({ ...tests, drop: 4 })
  }
  return fillRule(labels, width) ?? [{ text: '─'.repeat(width), color: SCREEN.rule }]
}

/** With separador off, the seal alone: '── ✔ provado ───'. */
function sealOnlySpans(seal: Span, width: number): Span[] {
  return fillRule([seal], width) ?? [{ text: '─'.repeat(width), color: SCREEN.rule }]
}

/** '── 15:41 · 6m 25s · 14 ferramentas · 3 arquivos · ✔ testes ──', filled with '─' to the width. */
export function turnRule(stats: TurnStats | null, durationMs: number, width: number, tzOffsetMinutes: number | null): string {
  return ruleSpans(stats, durationMs, width, tzOffsetMinutes).map(s => s.text).join('')
}

/** The thin rule above the person's prompt, with the time it was sent ('HH:MM') when known. */

// Stats by durationMs, read from the state once per load and kept here after: every closing rule drawn again (a scroll
// passes many) needs no trip to the engine. A turn that ends adds its own and redraws the screen (rememberTurn).
const known = new Map<string, TurnStats>()
let isLoaded = false

/** A finished turn's stats by its duration, the key TurnDuration and turn.complete share. */
export const turnStatsFor = (durationMs: number): TurnStats | null => known.get(String(durationMs)) ?? null

export function rememberTurn(key: string, stats: TurnStats): void {
  known.set(key, stats)
}

export function registerTurns(on: On): void {
  on('ui.render', { component: 'TurnDuration' }, async ($, e, next) => timed('TurnDuration', async () => {
    const flags = await getFlags($)
    if ((!flags.separador && !flags.selo) || e.surface !== 'terminal') return next(e)
    if (!isLoaded) {
      for (const [key, stats] of Object.entries(await read($, TURNS))) if (!known.has(key)) known.set(key, stats)
      isLoaded = true
    }
    const key = String(e.props.durationMs)
    const stats = known.get(key) ?? null
    // With separador off only a seal draws a rule; anything else is the engine's line.
    const seal = flags.selo ? sealLabel(stats?.seal) : null
    if (!flags.separador && seal === null) return next(e)
    const shown = flags.selo || stats === null ? stats : { ...stats, seal: null }
    const env = cachedEnv()
    const columns = e.viewport?.columns
    return memo('TurnDuration', `${e.requestId}|${key}|${stats !== null}|${columns}|${env?.tzOffsetMinutes}|${flagsVersion()}`, () => {
      const width = ruleWidth(columns)
      const spans = flags.separador ? ruleSpans(shown, e.props.durationMs, width, env?.tzOffsetMinutes ?? null) : sealOnlySpans(seal!, width)
      const { Box, Text } = $.ui.resolve(e)
      return (
        <Box key="realce-turn">
          <Text wrap="truncate-end">{spans.map(s => <Text color={s.color}>{s.text}</Text>)}</Text>
        </Box>
      )
    })
  }))
}

