  const failedTests = new Set([...text.slice(0, m.index!).matchAll(/^.*?✘ Test (.+?) failed after/gm)].map(f => f[1]))
  const failed = m[2] === 'passed' ? 0 : Math.min(total, failedTests.size || Number(m[4] ?? 1))
